(function () {
'use strict';
if (window.__TenantAiOcrLoaded) return;
window.__TenantAiOcrLoaded = true;
let pendingImageFile = null;
function qs(selector, root) {
return (root || document).querySelector(selector);
}
function toast(message, type) {
if (typeof window.showToast === 'function') window.showToast(message, type || 'info');
else if (typeof window.toast === 'function') window.toast(message, type || 'info');
else console[type === 'danger' || type === 'error' ? 'error' : 'log'](message);
}
function installStyles() {
if (document.getElementById('ai-ocr-style')) return;
const style = document.createElement('style');
style.id = 'ai-ocr-style';
style.textContent = '.ai-ocr-panel{border:1px solid #dbe5ef;border-radius:10px;background:#f8fafc;padding:12px}.ai-ocr-actions{display:flex;gap:8px;flex-wrap:wrap}.ai-ocr-actions .btn{min-height:38px}.ai-ocr-preview{margin-top:10px;min-height:92px;border:1px dashed #cbd5e1;border-radius:8px;background:#fff;display:grid;place-items:center;overflow:hidden;color:#64748b;font-size:12px}.ai-ocr-preview img{max-width:100%;max-height:180px;object-fit:contain}.ai-ocr-text{margin-top:10px}.ai-ocr-result{margin-top:8px;color:#475569;font-size:12px}.ai-ocr-result strong{color:#0f3768}@media(max-width:640px){.ai-ocr-actions .btn{flex:1 1 100%}}';
document.head.appendChild(style);
}
function enhancePersonForm() {
const form = qs('#personForm');
if (!form || form.dataset.aiOcrEnhanced === '1') return;
form.dataset.aiOcrEnhanced = '1';
installStyles();
const fullName = form.elements.fullName;
const host = fullName ? fullName.closest('.col-md-6') : qs('.modal-body .row', form);
if (!host) return;
const panel = document.createElement('div');
panel.className = 'col-12 ai-ocr-panel';
panel.innerHTML = [
'<div class="d-flex justify-content-between gap-2 align-items-center mb-2"><strong><i class="fa-solid fa-id-card"></i> OCR CCCD</strong><small data-ai-ocr-support></small></div>',
'<div class="ai-ocr-actions">',
'<button type="button" class="btn btn-outline-primary btn-sm" data-ai-ocr-action="camera"><i class="fa-solid fa-camera"></i> Chup giay to</button>',
'<button type="button" class="btn btn-outline-secondary btn-sm" data-ai-ocr-action="library"><i class="fa-solid fa-image"></i> Chon anh</button>',
'<button type="button" class="btn btn-primary btn-sm" data-ai-ocr-action="read"><i class="fa-solid fa-wand-magic-sparkles"></i> Doc OCR</button>',
'<button type="button" class="btn btn-outline-success btn-sm" data-ai-ocr-action="fill"><i class="fa-solid fa-pen-to-square"></i> Dien form</button>',
'</div>',
'<input type="file" accept="image/*" capture="environment" class="d-none" data-ai-ocr-camera>',
'<input type="file" accept="image/*" class="d-none" data-ai-ocr-library>',
'<div class="ai-ocr-preview" data-ai-ocr-preview>Chua co anh giay to</div>',
'<label class="visually-hidden" for="aiOcrTextInput">Text OCR CCCD</label>',
'<textarea id="aiOcrTextInput" class="form-control ai-ocr-text" rows="3" data-ai-ocr-text placeholder="Dan text OCR CCCD tai day neu trinh duyet chua ho tro OCR tu anh"></textarea>',
'<div class="ai-ocr-result" data-ai-ocr-result></div>',
].join('');
const row = qs('.modal-body .row', form);
row.insertBefore(panel, host);
bindPanel(panel, form);
document.dispatchEvent(new CustomEvent('tenant:ai-ocr-ready'));
}
function bindPanel(panel, form) {
const support = qs('[data-ai-ocr-support]', panel);
if (support) support.textContent = hasNativeOcr() ? 'OCR native san sang' : 'Fallback nhap text';
const camera = qs('[data-ai-ocr-camera]', panel);
const library = qs('[data-ai-ocr-library]', panel);
panel.addEventListener('click', event => {
const action = event.target.closest('[data-ai-ocr-action]')?.dataset.aiOcrAction || '';
if (action === 'camera') camera.click();
if (action === 'library') library.click();
if (action === 'read') readSelectedImage(panel);
if (action === 'fill') fillFromText(panel, form);
});
camera.addEventListener('change', () => selectFile(camera.files && camera.files[0], panel));
library.addEventListener('change', () => selectFile(library.files && library.files[0], panel));
}
function hasNativeOcr() {
return typeof window.TextDetector === 'function' && typeof window.createImageBitmap === 'function';
}
function selectFile(file, panel) {
if (!file) return;
if (!String(file.type || '').startsWith('image/')) {
toast('Chi ho tro file anh de OCR.', 'danger');
return;
}
pendingImageFile = file;
const preview = qs('[data-ai-ocr-preview]', panel);
const url = URL.createObjectURL(file);
preview.innerHTML = '<img alt="Anh giay to OCR" src="' + url + '">';
preview.querySelector('img').addEventListener('load', () => setTimeout(() => URL.revokeObjectURL(url), 60000), { once: true });
setResult(panel, 'Da chon anh. Bam Doc OCR neu trinh duyet ho tro, hoac dan text OCR vao o ben duoi.');
}
async function readSelectedImage(panel) {
if (!pendingImageFile) {
setResult(panel, 'Chua co anh de doc OCR.');
return;
}
if (!hasNativeOcr()) {
setResult(panel, 'Trinh duyet chua ho tro OCR native. Hay dan text OCR vao o ben duoi roi bam Dien form.');
return;
}
try {
setResult(panel, 'Dang doc OCR tren thiet bi...');
const bitmap = await window.createImageBitmap(pendingImageFile);
const detector = new window.TextDetector();
const blocks = await detector.detect(bitmap);
const text = blocks.map(block => block.rawValue || '').filter(Boolean).join('\n');
qs('[data-ai-ocr-text]', panel).value = text;
setResult(panel, text ? 'Da doc OCR, kiem tra lai text truoc khi dien form.' : 'Khong nhan duoc text tu anh.');
} catch (error) {
setResult(panel, error.message || 'Khong doc duoc OCR tu anh.');
}
}
function fillFromText(panel, form) {
const text = qs('[data-ai-ocr-text]', panel).value || '';
const data = parseCccdText(text);
const filled = applyCccdToPersonForm(form, data);
setResult(panel, renderExtracted(data, filled));
if (filled.length) {
document.dispatchEvent(new CustomEvent('tenant:ai-ocr-filled', { detail: { fields: filled, data } }));
toast('Da dien du lieu OCR vao form. Hay kiem tra lai truoc khi luu.', 'success');
}
}
function parseCccdText(text) {
const normalized = normalizeLines(text);
const joined = normalized.join('\n');
const identity = (joined.match(/\b\d{12}\b/) || joined.match(/\b\d{9}\b/) || [''])[0];
return {
identityNumber: identity,
fullName: parseName(normalized),
dateOfBirth: parseDate(joined),
gender: parseGender(normalized),
currentAddress: parseAddress(normalized),
rawText: String(text || '').trim(),
};
}
function normalizeLines(text) {
return String(text || '').split(/\r?\n| {2,}/).map(line => line.trim()).filter(Boolean);
}
function parseName(lines) {
for (let i = 0; i < lines.length; i++) {
const inline = lines[i].match(/(?:Ho va ten|Họ và tên|Full name)[:\s]+(.+)/i);
if (inline) return cleanName(inline[1]);
if (/ho.?va.?ten|full.?name/i.test(fold(lines[i])) && lines[i + 1]) return cleanName(lines[i + 1]);
}
const candidate = lines.find(line => /^[A-ZÀ-Ỹ\s]{6,}$/.test(line) && !/\d/.test(line) && !/CONG HOA|SOCIALIST|CAN CUOC|IDENTITY/i.test(fold(line)));
return candidate ? cleanName(candidate) : '';
}
function parseDate(text) {
const match = text.match(/\b(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})\b/);
if (!match) return '';
const day = match[1].padStart(2, '0');
const month = match[2].padStart(2, '0');
return match[3] + '-' + month + '-' + day;
}
function parseGender(lines) {
for (let i = 0; i < lines.length; i++) {
const folded = fold(lines[i]);
const inline = folded.match(/(?:gioi tinh|sex)[:\s]+(nam|nu|male|female)\b/);
if (inline) return inline[1] === 'nu' || inline[1] === 'female' ? 'Nữ' : 'Nam';
if ((folded.includes('gioi tinh') || folded === 'sex') && lines[i + 1]) {
const next = fold(lines[i + 1]);
if (/\b(nu|female)\b/.test(next)) return 'Nữ';
if (/\b(nam|male)\b/.test(next)) return 'Nam';
}
}
return '';
}
function parseAddress(lines) {
for (let i = 0; i < lines.length; i++) {
const folded = fold(lines[i]);
const inline = lines[i].match(/(?:Noi thuong tru|Nơi thường trú|Que quan|Quê quán|Place of residence)[:\s]+(.+)/i);
if (inline) return inline[1].trim();
if ((folded.includes('noi thuong tru') || folded.includes('que quan') || folded.includes('place of residence')) && lines[i + 1]) return lines[i + 1].trim();
}
return '';
}
function applyCccdToPersonForm(form, data) {
const mapping = {
identityNumber: data.identityNumber,
fullName: data.fullName,
dateOfBirth: data.dateOfBirth,
gender: data.gender,
currentAddress: data.currentAddress,
};
const filled = [];
Object.keys(mapping).forEach(name => {
const value = mapping[name];
const input = form.elements[name];
if (!input || !value) return;
input.value = value;
input.dispatchEvent(new Event('input', { bubbles: true }));
input.dispatchEvent(new Event('change', { bubbles: true }));
filled.push(name);
});
return filled;
}
function renderExtracted(data, filled) {
const pairs = [
['CCCD', data.identityNumber],
['Ho ten', data.fullName],
['Ngay sinh', data.dateOfBirth],
['Gioi tinh', data.gender],
['Dia chi', data.currentAddress],
].filter(pair => pair[1]);
if (!pairs.length) return 'Chua trich xuat duoc truong nao tu text OCR.';
return '<strong>Da nhan dien:</strong> ' + pairs.map(pair => esc(pair[0]) + ': ' + esc(pair[1])).join(' - ') + '. Truong da dien: ' + esc(filled.join(', '));
}
function setResult(panel, html) {
const result = qs('[data-ai-ocr-result]', panel);
if (result) result.innerHTML = html;
}
function cleanName(value) {
return String(value || '').replace(/[^A-Za-zÀ-ỹ\s']/g, ' ').replace(/\s+/g, ' ').trim();
}
function esc(value) {
return String(value == null ? '' : value).replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[c]));
}
function fold(value) {
return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
function boot() {
enhancePersonForm();
}
window.TenantAiOcr = Object.freeze({
enhancePersonForm,
parseCccdText,
applyCccdToPersonForm,
hasNativeOcr,
});
document.addEventListener('shown.bs.modal', event => {
if (event.target && event.target.id === 'personModal') window.setTimeout(boot, 30);
});
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
